package com.mediconnect.office.api;
import java.util.*; import com.mediconnect.office.application.OfficeService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/offices") @Tag(name="Admin Offices") @SecurityRequirement(name="bearerAuth") public class OfficeController { private final OfficeService service; public OfficeController(OfficeService service){this.service=service;} @GetMapping @Operation(summary="List offices",description="ADMIN-only office management endpoint.") public List<OfficeResponse> list(){return service.list();} @PostMapping @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Create office",description="Creates a clinic office/consulting room.") public OfficeResponse create(@Valid @RequestBody OfficeRequest request){return service.create(request);} @PutMapping("/{id}") @Operation(summary="Update office",description="Updates office location and active state.") public OfficeResponse update(@PathVariable UUID id,@Valid @RequestBody OfficeRequest request){return service.update(id,request);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(summary="Delete office",description="Deletes an office when it is no longer required.") public void delete(@PathVariable UUID id){service.delete(id);} }
